import {
  AlertTriangle,
  ArrowDown,
  ArrowUp,
  Bold,
  Check,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Download,
  Eye,
  EyeOff,
  GitBranch,
  Heading2,
  Image,
  Italic,
  Keyboard,
  Link,
  List,
  ListOrdered,
  LocateFixed,
  Lock,
  Map,
  Maximize2,
  Minus,
  MousePointer2,
  PanelRightClose,
  Plus,
  Quote,
  Redo2,
  Save,
  Search,
  Settings2,
  Trash2,
  Underline,
  Undo2,
  Unplug,
  Unlock,
  UserRound,
  UsersRound,
  WandSparkles,
  X,
  ZoomIn,
  ZoomOut,
  createIcons
} from "lucide";

const icons = {
  AlertTriangle,
  ArrowDown,
  ArrowUp,
  Bold,
  Check,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Download,
  Eye,
  EyeOff,
  GitBranch,
  Heading2,
  Image,
  Italic,
  Keyboard,
  Link,
  List,
  ListOrdered,
  LocateFixed,
  Lock,
  Map,
  Maximize2,
  Minus,
  MousePointer2,
  PanelRightClose,
  Plus,
  Quote,
  Redo2,
  Save,
  Search,
  Settings2,
  Trash2,
  Underline,
  Undo2,
  Unplug,
  Unlock,
  UserRound,
  UsersRound,
  WandSparkles,
  X,
  ZoomIn,
  ZoomOut
};

export function refreshIcons(root = document) {
  createIcons({ icons, attrs: { "aria-hidden": "true", focusable: "false" }, nameAttr: "data-lucide" });
  root.querySelectorAll("svg.lucide").forEach(icon => icon.setAttribute("aria-hidden", "true"));
}
